prts.feedbackvariables:
exactok:is(equal(ans1,ta));
zerook:if exactok then false else is(equal(ans1,wrongzero));
baseok:if exactok then false else is(equal(ans1,wrongbase));
factorok:if exactok then false else is(equal(ans1,wrongfactor));
recipok:if exactok then false else is(equal(ans1,wrongrecip));

scoreval:
if exactok then 1
elseif factorok then 0.40
elseif baseok then 0.35
elseif recipok then 0.20
elseif zerook then 0.10
else 0;

ok:true;
if is(equal(ans1,ta)) then ok:false;
if is(equal(ans1,wrongzero)) then ok:false;
if is(equal(ans1,wrongbase)) then ok:false;
if is(equal(ans1,wrongfactor)) then ok:false;
if is(equal(ans1,wrongrecip)) then ok:false;
